def shape_spec(primary, category):
    for profile, pattern, geometry, view in TYPE_RULES:
        if re.search(pattern, primary, re.I):
            return {"profile": profile, "geometry": geometry, "view": view}
    if category.startswith("primitive_"):
        return {"profile": category, "geometry": "Preserve the exact authored geometric shape, dimensions, material and proportions. Planar faces remain flat and intended curved surfaces regular. Keep genuine openings, cut-outs and explicit shape deformations; add no unrelated product features.", "view": None}
    if category in CATEGORY_RULES:
        profile, geometry = CATEGORY_RULES[category]
        return {"profile": profile, "geometry": geometry, "view": None}
    return None
